es'])):?><div class="professional-tags"><?php foreach($c['specialties'] as $x):?><span><?= htmlspecialchars((string)$x) ?></span><?php endforeach;?></div><?php endif;?><p><?= nl2br(htmlspecialchars((string)($c['bio']?:'Henüz biyografi eklenmedi.'))) ?></p><?php if(!empty($c['formations'])):?><h3>Tercih edilen dizilişler</h3><p><?= htmlspecialchars(implode(' · ',$c['formations'])) ?></p><?php endif;?><?php if(!empty($c['achievements_text'])):?><h3>Başarılar</h3><p><?= nl2br(htmlspecialchars((string)$c['achievements_text'])) ?></p><?php endif;?></aside></div></main><?php require __DIR__.'/../layouts/footer.php'; ?>
